// En orderService.ts
import { OrderFE /*...*/ } from "../../types/order.types"; // Necesitas esta interfaz
import { apiClient } from "../apiClient"; // Asume que tienes un apiClient configurado

export interface CreateOrderFrontendData extends FormData {} // Solo para tipado

export const orderService = {
  async createOrderPwa(
    formData: FormData,
    authToken: string
  ): Promise<OrderFE> {
    // OrderFE es lo que esperas de respuesta
    const response = await apiClient.post<OrderFE>("/orders", formData, {
      headers: {
        Authorization: `Bearer ${authToken}`,
        "Content-Type": "multipart/form-data", // Axios lo suele detectar, pero no está de más
      },
    });
    return response.data;
  },
  // ... otros métodos ...
};
